/**
 * The First Walk
 * --------------
 * Enoch begins a daily walk — a habit of quiet steps that makes room for the presence of God. Stage: a dawn road through early fields, a lone figure walking, the city behind; cool morning light, birds lifting.
 *
 * Palette 0x2d1a0e → 0x060402 · light: dusk · hero: city
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./enoch-kit.js.
 */

import { THREE, createScene, cityGate, person, birds } from './enoch-kit.js';

const BG = 0x2d1a0e;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2597137664, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* hero: the city gate */
    cityGate(W, group, 0, 0, -8, 1.1, { stone: 0x060402, trim: 0x050302 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x2d1a0e, bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: 0.50, s: 1.01 });

    /* birds: slow circles high above */
    birds(W, group, 8, 55, { y: 26 });

    return W.finish();
}

export default { build };
